"use client";

import { type CSSProperties, type ImgHTMLAttributes, type Ref, useEffect, useRef, useState } from "react";
import { cx, flag } from "../utils/cx";

export type ImageProps = Omit<ImgHTMLAttributes<HTMLImageElement>, "alt" | "placeholder"> & {
  /** Required. Use `alt=""` only for decorative images. */
  alt: string;
  /** Aspect ratio of the frame, e.g. `"3 / 2"`. Reserves the space so nothing shifts when the image arrives. */
  ratio?: string;
  /** A CSS color or a tiny data URL / image URL shown (blurred) until the image has loaded. */
  placeholder?: string;
  /** Slowly scale to 1.04 when the frame is hovered or focused (the gallery card behavior). */
  zoom?: boolean;
  fit?: "cover" | "contain";
  frameClassName?: string;
  ref?: Ref<HTMLImageElement>;
};

const isImageSource = (s: string) => /^(data:|blob:|https?:|\/|\.)/.test(s);

/**
 * An image in a fixed frame with a blur-up placeholder and a fade-in. Lazy and async-decoded by default. Without JS, or if the
 * image is already complete when React hydrates, it is shown at once instead of fading.
 */
export function Image({
  ratio,
  placeholder,
  zoom,
  fit = "cover",
  frameClassName,
  className,
  loading = "lazy",
  decoding = "async",
  onLoad,
  onError,
  ref,
  ...rest
}: ImageProps) {
  const inner = useRef<HTMLImageElement | null>(null);
  const [state, setState] = useState<"idle" | "loading" | "loaded" | "error">("idle");
  useEffect(() => {
    // "idle" (server HTML, no JS) leaves the image visible; only once hydrated do we hide it to fade it in
    const img = inner.current;
    setState(img?.complete && img.naturalWidth > 0 ? "loaded" : img?.complete ? "error" : "loading");
  }, []);
  const style: CSSProperties = {
    ...(ratio ? { aspectRatio: ratio } : null),
    ...(placeholder
      ? isImageSource(placeholder)
        ? { backgroundImage: `url("${placeholder}")` }
        : { backgroundColor: placeholder }
      : null),
  };
  return (
    <span
      className={cx("hm-image", frameClassName)}
      style={style}
      data-state={state}
      data-zoom={flag(zoom)}
      data-fit={fit}
    >
      {/* biome-ignore lint/a11y/useAltText: alt is a required prop and arrives through rest */}
      <img
        {...rest}
        ref={(node) => {
          inner.current = node;
          if (typeof ref === "function") return ref(node);
          if (ref) ref.current = node;
        }}
        loading={loading}
        decoding={decoding}
        className={cx("hm-image-img", className)}
        onLoad={(e) => {
          setState("loaded");
          onLoad?.(e);
        }}
        onError={(e) => {
          setState("error");
          onError?.(e);
        }}
      />
    </span>
  );
}
